cp /runtime/worker.conf /runtime/worker.conf.bak && printf '{
  "enabled": false,
  "work_units": 60000
}
' > /runtime/worker.conf && cat /runtime/worker.conf

printf '{
  "enabled": false,
  "work_units": 60000
}
' > /runtime/worker.conf && cat /runtime/worker.conf

printf '{
  "enabled": true,
  "work_units": 1
}
' > /runtime/worker.conf; sleep 2; ps -eo pid,ppid,stat,pcpu,comm,args --sort=-pcpu | head -6; echo '---status---'; cat /runtime/status.json; echo; top -b -n1 | grep '%Cpu'

printf '{
  "enabled": false,
  "work_units": 1
}
' > /runtime/worker.conf; sleep 3; ps -eo pid,ppid,stat,pcpu,comm,args --sort=-pcpu | head -6; echo '---status---'; cat /runtime/status.json; echo; cat /runtime/worker.conf

printf '{
  "enabled": false,
  "work_units": 60000
}
' > /runtime/worker.conf; cat /runtime/worker.conf; echo '---'; sleep 2; ps -eo pid,ppid,stat,pcpu,comm,args --sort=-pcpu | head -6; echo '---status---'; cat /runtime/status.json; echo
